			mmUpdateIdentityProvider.t.Errorf("IdentityProviderUseCaseMock.UpdateIdentityProvider got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdateIdentityProvider.UpdateIdentityProviderMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
