// MinimockUpdateIdentityProviderInspect logs each unmet expectation
func (m *IdentityProviderUseCaseMock) MinimockUpdateIdentityProviderInspect() {
	for _, e := range m.UpdateIdentityProviderMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to IdentityProviderUseCaseMock.UpdateIdentityProvider at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateIdentityProviderCounter := mm_atomic.LoadUint64(&m.afterUpdateIdentityProviderCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateIdentityProviderMock.defaultExpectation != nil && afterUpdateIdentityProviderCounter < 1 {
		if m.UpdateIdentityProviderMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to IdentityProviderUseCaseMock.UpdateIdentityProvider at\n%s", m.UpdateIdentityProviderMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to IdentityProviderUseCaseMock.UpdateIdentityProvider at\n%s with params: %#v", m.UpdateIdentityProviderMock.defaultExpectation.expectationOrigins.origin, *m.UpdateIdentityProviderMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateIdentityProvider != nil && afterUpdateIdentityProviderCounter < 1 {
		m.t.Errorf("Expected call to IdentityProviderUseCaseMock.UpdateIdentityProvider at\n%s", m.funcUpdateIdentityProviderOrigin)
	}

	if !m.UpdateIdentityProviderMock.invocationsDone() && afterUpdateIdentityProviderCounter > 0 {
		m.t.Errorf("Expected %d calls to IdentityProviderUseCaseMock.UpdateIdentityProvider at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateIdentityProviderMock.expectedInvocations), m.UpdateIdentityProviderMock.expectedInvocationsOrigin, afterUpdateIdentityProviderCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *IdentityProviderUseCaseMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateIdentityProviderInspect()

			m.MinimockDeleteIdentityProviderInspect()

			m.MinimockDiscoverOIDCInspect()

			m.MinimockGetIdentityProviderInspect()

			m.MinimockGetIdentityProviderUsageInspect()

			m.MinimockGetIdentityProvidersInspect()

			m.MinimockGetPartitionsWithProvidersInspect()

			m.MinimockPatchIdentityProviderInspect()

			m.MinimockUpdateIdentityProviderInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *IdentityProviderUseCaseMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *IdentityProviderUseCaseMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateIdentityProviderDone() &&
		m.MinimockDeleteIdentityProviderDone() &&
		m.MinimockDiscoverOIDCDone() &&
		m.MinimockGetIdentityProviderDone() &&
		m.MinimockGetIdentityProviderUsageDone() &&
		m.MinimockGetIdentityProvidersDone() &&
		m.MinimockGetPartitionsWithProvidersDone() &&
		m.MinimockPatchIdentityProviderDone() &&
		m.MinimockUpdateIdentityProviderDone()
}
